DROP POLICY IF EXISTS "activity_logs_select_all" ON public.activity_logs; DROP POLICY IF EXISTS "Allow authenticated users to view activity logs" ON public.activity_logs; DROP POLICY IF EXISTS "Users can view their own activity" ON public.activity_logs; DROP POLICY IF EXISTS "activity_logs_hospital_read" ON public.activity_logs; CREATE POLICY "activity_logs_hospital_read" ON public.activity_logs FOR SELECT USING (public.user_belongs_to_hospital(auth.uid(), hospital_id)); DROP POLICY IF EXISTS "activity_logs_self_insert" ON public.activity_logs; CREATE POLICY "activity_logs_self_insert" ON public.activity_logs FOR INSERT WITH CHECK ( user_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid()) AND public.user_belongs_to_hospital(auth.uid(), hospital_id) ); DROP POLICY IF EXISTS "notifications_select_all" ON public.notifications; DROP POLICY IF EXISTS "Users can view all notifications" ON public.notifications; DROP POLICY IF EXISTS "notifications_hospital_recipient_read" ON public.notifications; CREATE POLICY "notifications_hospital_recipient_read" ON public.notifications FOR SELECT USING ( recipient_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid()) OR ( hospital_id IS NOT NULL AND public.user_belongs_to_hospital(auth.uid(), hospital_id) AND EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('admin') AND ur.hospital_id = hospital_id ) ) ); DROP POLICY IF EXISTS "prescriptions_hospital_read_v2" ON public.prescriptions; CREATE POLICY "prescriptions_hospital_read_v2" ON public.prescriptions FOR SELECT USING ( hospital_id IS NOT NULL AND public.user_belongs_to_hospital(auth.uid(), hospital_id) ); DROP POLICY IF EXISTS "invoices_select_all" ON public.invoices; DROP POLICY IF EXISTS "invoices_hospital_billing_read" ON public.invoices; CREATE POLICY "invoices_hospital_billing_read" ON public.invoices FOR SELECT USING ( public.user_belongs_to_hospital(auth.uid(), hospital_id) AND EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('admin','doctor','receptionist','nurse') AND ur.hospital_id = hospital_id ) ); DROP POLICY IF EXISTS "feature_flags_hospital_or_global_read" ON public.feature_flags; CREATE POLICY "feature_flags_hospital_or_global_read" ON public.feature_flags FOR SELECT USING ( hospital_id IS NULL OR public.user_belongs_to_hospital(auth.uid(), hospital_id) ); DROP POLICY IF EXISTS "feature_flags_admin_write" ON public.feature_flags; CREATE POLICY "feature_flags_admin_write" ON public.feature_flags FOR ALL USING ( EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('admin') AND (ur.hospital_id = hospital_id OR hospital_id IS NULL) ) );